package com.kagafei.g510d2voice;
import android.Manifest;import android.app.*;import android.os.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.media.*;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.journeyapps.barcodescanner.*;import com.journeyapps.barcodescanner.camera.CameraSettings;import java.util.*;
public class MainActivity extends Activity{
 static class P{String n,c,img;int p;P(String n,int p,String c,String img){this.n=n;this.p=p;this.c=c;this.img=img;}}
 Map<String,P[]> cat=new LinkedHashMap<>();Map<String,P> by=new HashMap<>();Map<String,Integer> cart=new LinkedHashMap<>();DecoratedBarcodeView sc;GridLayout grid;TextView cv,tv,st;Spinner cams;MediaPlayer guide,beep;String last="";long lastAt;
 public void onCreate(Bundle b){super.onCreate(b);setVolumeControlStream(AudioManager.STREAM_MUSIC);setContentView(R.layout.activity_main);sc=findViewById(R.id.scanner);grid=findViewById(R.id.grid);cv=findViewById(R.id.cart);tv=findViewById(R.id.total);st=findViewById(R.id.status);cams=findViewById(R.id.cameras);seed();tabs();cams.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Camera 0","Camera 1","Camera 2","Camera 3"}));findViewById(R.id.change).setOnClickListener(v->camera(cams.getSelectedItemPosition()));findViewById(R.id.replay).setOnClickListener(v->playGuide());findViewById(R.id.clear).setOnClickListener(v->{cart.clear();refresh();playGuide();});findViewById(R.id.pay).setOnClickListener(v->pay());guide=MediaPlayer.create(this,R.raw.welcome_guidance);beep=MediaPlayer.create(this,R.raw.scan_beep);new Handler().postDelayed(this::playGuide,500);if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},7);else camera(0);show("食品");}
 void seed(){String[] cats={"食品","飲料","青果","日用品","精肉・鮮魚","惣菜"};String[][] n={{"食パン","牛乳","たまご","おにぎり","カレー","ヨーグルト"},{"緑茶","水","コーヒー","オレンジジュース","コーラ","炭酸水"},{"りんご","バナナ","みかん","トマト","キャベツ","じゃがいも"},{"ティッシュ","洗剤","歯ブラシ","ラップ","スポンジ","ごみ袋"},{"牛肉","豚肉","鶏肉","生鮭","えび","ひき肉"},{"幕の内弁当","寿司盛合せ","唐揚げ","ポテトサラダ","サンドイッチ","プリン"}};String[][] im={{"bread","milk","eggs","onigiri","curry","yogurt"},{"green_tea","water","coffee","orange_juice","cola","sparkling_water"},{"apple","banana","mandarin","tomato","cabbage","potato"},{"tissue","detergent","toothbrush","wrap","sponge","garbage_bag"},{"beef","pork","chicken","salmon","shrimp","minced_meat"},{"bento","sushi_pack","karaage","potato_salad","sandwich","pudding"}};int[][] pr={{198,218,298,138,258,158},{128,108,148,198,168,118},{158,198,398,258,198,298},{398,348,198,258,128,298},{680,480,398,580,498,458},{598,798,398,258,328,198}};int k=0;for(int a=0;a<6;a++){P[] ps=new P[6];for(int i=0;i<6;i++){String code=ean("49012345"+String.format(Locale.US,"%04d",k++));ps[i]=new P(n[a][i],pr[a][i],code,im[a][i]);by.put(code,ps[i]);}cat.put(cats[a],ps);}}
 String ean(String s){int x=0;for(int i=0;i<12;i++)x+=(s.charAt(i)-48)*(i%2==0?1:3);return s+((10-x%10)%10);}void tabs(){LinearLayout t=findViewById(R.id.tabs);for(String k:cat.keySet()){Button b=new Button(this);b.setText(k);b.setOnClickListener(v->show(k));t.addView(b,new LinearLayout.LayoutParams(145,-1));}}
 void camera(int id){sc.pause();CameraSettings cs=new CameraSettings();cs.setRequestedCameraId(id);sc.getBarcodeView().setCameraSettings(cs);sc.getBarcodeView().setDecoderFactory(new DefaultDecoderFactory(Arrays.asList(BarcodeFormat.EAN_13,BarcodeFormat.EAN_8,BarcodeFormat.UPC_A,BarcodeFormat.QR_CODE)));sc.decodeContinuous(new BarcodeCallback(){public void barcodeResult(BarcodeResult r){scan(r.getText());}public void possibleResultPoints(List<ResultPoint>x){}});sc.resume();}
 void scan(String code){long now=System.currentTimeMillis();if(code.equals(last)&&now-lastAt<2500)return;last=code;lastAt=now;P p=by.get(code);if(p==null){st.setText("未登録JAN: "+code);return;}if(beep!=null){beep.seekTo(0);beep.start();}cart.put(code,cart.getOrDefault(code,0)+1);st.setText(p.n+" "+p.p+"円を登録しました");refresh();}
 void playGuide(){if(guide!=null){if(guide.isPlaying())guide.pause();guide.seekTo(0);guide.start();}st.setText("商品のバーコードを読み取らせてください");}
 void show(String k){grid.removeAllViews();for(P p:cat.get(k)){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams q=new GridLayout.LayoutParams();q.width=0;q.height=0;q.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.setMargins(4,4,4,4);c.setLayoutParams(q);ImageView im=new ImageView(this);im.setImageResource(getResources().getIdentifier(p.img,"drawable",getPackageName()));im.setScaleType(ImageView.ScaleType.CENTER_CROP);c.addView(im,new LinearLayout.LayoutParams(-1,0,1f));Button b=new Button(this);b.setText(p.n+" "+p.p+"円 ＋");b.setOnClickListener(v->scan(p.c));c.addView(b,new LinearLayout.LayoutParams(-1,50));grid.addView(c);}}
 void refresh(){int sum=0;StringBuilder s=new StringBuilder();for(String x:cart.keySet()){P p=by.get(x);int q=cart.get(x);sum+=p.p*q;s.append(p.n).append(" × ").append(q).append("\n");}cv.setText(cart.isEmpty()?"商品はありません":s);tv.setText("合計 "+(sum+(int)(sum*.1))+"円");}void pay(){if(cart.isEmpty())return;String[] x={"カード","電子マネー","QR","現金"};new AlertDialog.Builder(this).setTitle("お支払い方法").setItems(x,(d,w)->new AlertDialog.Builder(this).setTitle("会計完了").setMessage("お支払いを受け付けました").setPositiveButton("完了",(a,z)->{cart.clear();refresh();}).show()).show();}
 protected void onResume(){super.onResume();if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)sc.resume();}protected void onPause(){sc.pause();super.onPause();}protected void onDestroy(){if(guide!=null)guide.release();if(beep!=null)beep.release();super.onDestroy();}public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==7&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)camera(0);}
}
